B.b7P=new A.eE([B.jH,"Find a masjid near you","Mosques around you, on a map","/masajid"])
B.b7N=new A.eE([B.DS,"Jumu\u2019ah and prayer times","Set your masjid\u2019s Friday time","/prayer"])
